-- Catálogo de instrumentos BVM (vector de precios BCU), carga inicial del 28/10/2026.
-- Se actualiza desde la app con "↻ Actualizar catálogo" en Cartera → + Agregar.

create table if not exists instrumentos (
  isin text primary key,
  codigo text,
  nombre text not null,
  especie text,
  moneda text,
  cupon numeric,
  vencimiento date,
  precio numeric,
  cupon_corrido numeric,
  fecha_precio date,
  updated_at timestamptz not null default now()
);
-- Datos que completa el usuario (la sincronización con la BVM no los pisa).
alter table instrumentos add column if not exists cupon_manual numeric;
alter table instrumentos add column if not exists vencimiento_manual date;
alter table instrumentos add column if not exists frecuencia integer;
alter table instrumentos enable row level security;
drop policy if exists "authenticated only instrumentos" on instrumentos;
create policy "authenticated only instrumentos" on instrumentos
  for all using (auth.role() = 'authenticated') with check (auth.role() = 'authenticated');

on conflict (isin) do update set codigo=excluded.codigo,nombre=excluded.nombre,especie=excluded.especie,moneda=excluded.moneda,cupon=excluded.cupon,vencimiento=excluded.vencimiento,precio=excluded.precio,cupon_corrido=excluded.cupon_corrido,fecha_precio=excluded.fecha_precio,updated_at=now();
